import {
  Body,
  Head as EmailHead,
  Html,
  Preview,
  Section,
  Row,
  Column,
  Text,
  Img,
} from "jsx-email";
import { Fragment } from "react";

import { DefaultFonts } from "@/components/email/font-default";
import { EmailTailwind } from "@/components/email/email-theme";
import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

export type PaymentTimelineVariant = "3-steps" | "4-steps";

export interface PaymentTimelineProps {
  theme?: EmailTheme;
  variant?: PaymentTimelineVariant;
  amount?: string;
  firstDate?: string;
  secondDate?: string;
  thirdDate?: string;
  fourthDate?: string;
}

const fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const responsiveStyles = `
  .payment-timeline-mobile { display: none; }
  @media only screen and (max-width: 430px) {
    .payment-timeline-desktop { display: none !important; }
    .payment-timeline-mobile { display: block !important; }
  }
`;

const textStyle = {
  fontFamily,
  margin: 0,
} as const;

const getDateAlignment = (
  index: number,
  length: number
): "center" | "left" | "right" => {
  if (index === 0) {
    return "left";
  }
  return index === length - 1 ? "right" : "center";
};

const Dot = ({ checked, dark }: { checked?: boolean; dark: boolean }) => (
  <Section
    style={{
      backgroundColor: dark ? "#030712" : "#d1d5db",
      borderRadius: "9999px",
      height: "12px",
      lineHeight: checked ? "10px" : "12px",
      margin: "0 auto",
      textAlign: "center",
      width: "12px",
    }}
  >
    {checked ? (
      <Img
        alt=""
        src={emailAsset("timelines/icon-check-white.png")}
        style={{ marginBottom: "1px" }}
        width="8"
      />
    ) : (
      <>&zwj;</>
    )}
  </Section>
);

export const PaymentTimelineSection = ({
  amount = "$9.99",
  firstDate = "Paid: 17/11",
  fourthDate = "17/02",
  secondDate = "17/12",
  thirdDate = "17/01",
  variant = "3-steps",
}: Omit<PaymentTimelineProps, "theme">) => {
  const dates =
    variant === "4-steps"
      ? [firstDate, secondDate, thirdDate, fourthDate]
      : [firstDate, secondDate, thirdDate];
  return (
    <>
      <style>{responsiveStyles}</style>
      <Section style={{ backgroundColor: "#f1f5f9", width: "100%" }}>
        <Fragment>
          <Row>
            <Column>&zwj;</Column>
            <Column
              style={{
                backgroundColor: "#fffffe",
                maxWidth: "100%",
                paddingBottom: "44px",
                width: "600px",
              }}
            >
              <Section style={{ width: "100%" }}>
                <Fragment>
                  <Row>
                    <Column style={{ padding: "0 24px" }}>
                      <Section style={{ lineHeight: "44px" }}>&zwj;</Section>
                      <Section
                        className="payment-timeline-desktop"
                        style={{ tableLayout: "fixed", width: "100%" }}
                      >
                        <Fragment>
                          <Row>
                            {dates.map((date, index) => (
                              <Column key={date}>
                                <Section style={{ width: "100%" }}>
                                  <Fragment>
                                    <Row>
                                      <Column>
                                        {(() => {
                                          if (index === 0) {
                                            return null;
                                          }
                                          return (
                                            <Section
                                              style={{
                                                backgroundColor:
                                                  index <= 1
                                                    ? "#030712"
                                                    : "#d1d5db",
                                                height: "1px",
                                                lineHeight: "1px",
                                              }}
                                            >
                                              &zwj;
                                            </Section>
                                          );
                                        })()}
                                      </Column>
                                      <Column style={{ width: "16px" }}>
                                        <Dot
                                          checked={index === 0}
                                          dark={index <= 1}
                                        />
                                      </Column>
                                      <Column>
                                        {(() => {
                                          if (index === dates.length - 1) {
                                            return null;
                                          }
                                          return (
                                            <Section
                                              style={{
                                                backgroundColor:
                                                  index === 0
                                                    ? "#030712"
                                                    : "#d1d5db",
                                                height: "1px",
                                                lineHeight: "1px",
                                              }}
                                            >
                                              &zwj;
                                            </Section>
                                          );
                                        })()}
                                      </Column>
                                    </Row>
                                  </Fragment>
                                </Section>
                              </Column>
                            ))}
                          </Row>
                          <Row>
                            <Column
                              colSpan={dates.length}
                              style={{ lineHeight: "8px" }}
                            >
                              &zwj;
                            </Column>
                          </Row>
                          <Row>
                            {dates.map((date, index) => (
                              <Column
                                key={date}
                                style={{
                                  textAlign: getDateAlignment(
                                    index,
                                    dates.length
                                  ),
                                  verticalAlign: "top",
                                }}
                              >
                                <Text
                                  style={{
                                    ...textStyle,
                                    color: "#030712",
                                    fontSize: "12px",
                                    fontWeight: 600,
                                    lineHeight: "16px",
                                  }}
                                >
                                  {date}
                                </Text>
                                <Text
                                  style={{
                                    ...textStyle,
                                    color: "#4b5563",
                                    fontSize: "10px",
                                    lineHeight: "16px",
                                  }}
                                >
                                  {amount}
                                </Text>
                              </Column>
                            ))}
                          </Row>
                        </Fragment>
                      </Section>
                      <Section className="payment-timeline-mobile">
                        {dates.map((date, index) => (
                          <Section key={date} style={{ display: "flex" }}>
                            <Section>
                              <Section style={{ margin: "2px 0" }}>
                                <Dot checked={index === 0} dark={index <= 1} />
                              </Section>
                              {(() => {
                                if (index === dates.length - 1) {
                                  return null;
                                }
                                return (
                                  <Section
                                    style={{
                                      backgroundColor:
                                        index === 0 ? "#030712" : "#d1d5db",
                                      height: "48px",
                                      margin: "0 auto",
                                      width: "1px",
                                    }}
                                  />
                                );
                              })()}
                            </Section>
                            <Section style={{ paddingLeft: "8px" }}>
                              <Text
                                style={{
                                  ...textStyle,
                                  color: "#030712",
                                  fontSize: "12px",
                                  fontWeight: 600,
                                  lineHeight: "16px",
                                }}
                              >
                                {date}
                              </Text>
                              <Text
                                style={{
                                  ...textStyle,
                                  color: "#4b5563",
                                  fontSize: "10px",
                                  lineHeight: "16px",
                                }}
                              >
                                {amount}
                              </Text>
                            </Section>
                          </Section>
                        ))}
                      </Section>
                    </Column>
                  </Row>
                </Fragment>
              </Section>
            </Column>
            <Column>&zwj;</Column>
          </Row>
        </Fragment>
      </Section>
    </>
  );
};

export const PaymentTimeline = ({
  theme = defaultTheme,
  ...props
}: PaymentTimelineProps) => (
  <Html>
    <EmailHead>
      <DefaultFonts />
    </EmailHead>
    <Preview>Payment timeline</Preview>
    <EmailTailwind theme={theme}>
      <Body className="m-0">
        <PaymentTimelineSection {...props} />
      </Body>
    </EmailTailwind>
  </Html>
);

PaymentTimeline.PreviewProps = {
  theme: defaultTheme,
  variant: "3-steps",
} satisfies PaymentTimelineProps;

const ASSET_ORIGIN = "https://www.emailcn.run";

const palettes = [
  ["4F46E5", "FFFFFF"],
  ["0F766E", "FFFFFF"],
  ["C2410C", "FFFFFF"],
  ["7E22CE", "FFFFFF"],
  ["0369A1", "FFFFFF"],
  ["BE123C", "FFFFFF"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getLabel = (path: string) => {
  const fileName = path.split("/").at(-1) ?? "emailcn";

  return fileName
    .replace(/\.[^.]+$/, "")
    .replace(/^(?:logo|badge|icon)-/, "")
    .replaceAll("-", " ")
    .replaceAll(/\b\w/g, (character) => character.toUpperCase());
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const seed = getSeed(normalizedPath);
  const hash = hashString(seed);
  const [background, foreground] =
    palettes[hash % palettes.length] ?? palettes[0];
  const [width, height] = getDimensions(normalizedPath);

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return `https://api.dicebear.com/9.x/lorelei/png?seed=${encodeURIComponent(
      seed
    )}&size=${Math.max(width, height)}&backgroundColor=${background.toLowerCase()}`;
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (
    /(?:icon|btc|eth|logo|insignia|badge-app|badge-google)/i.test(
      normalizedPath
    )
  ) {
    return `https://placehold.co/${width}x${height}/${background}/${foreground}.png?text=${encodeURIComponent(
      getLabel(normalizedPath)
    )}`;
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
